/**
 * Validates the raw JSearch response before it is normalized.
 */
function validateJSearchResponse(response) {
  if (!response || typeof response !== 'object' || Array.isArray(response)) {
    throw new Error('JSearch returned an invalid response body.');
  }

  if (response.status !== 'OK') {
    throw new Error(`JSearch request failed with status: ${String(response.status)}`);
  }

  if (!Array.isArray(response.data)) {
    throw new Error('JSearch response is missing the expected data array.');
  }

  return {
    ...response,
    validation: {
      source: 'JSearch',
      job_count: response.data.length,
      validated_at: new Date().toISOString(),
    },
  };
}

return $input.all().map((item) => ({
  json: validateJSearchResponse(item.json),
}));

/**
 * Converts every validated JSearch record into a canonical job object.
 * This node only normalizes data; it does not filter, score, or persist jobs.
 */
function normalizeText(value) {
  if (typeof value !== 'string') return null;
  const normalized = value.replace(/\s+/g, ' ').trim();
  return normalized || null;
}

function normalizeMultilineText(value) {
  if (typeof value !== 'string') return null;
  const normalized = value.replace(/\r\n?/g, '\n').split('\n')
    .map((line) => line.replace(/[ \t]+/g, ' ').trim()).join('\n').trim();
  return normalized || null;
}

function toArray(value) {
  if (value === null || value === undefined) return [];
  return Array.isArray(value) ? value : [value];
}

function uniqueStrings(values) {
  const seen = new Set();
  return toArray(values).flatMap(toArray).map(normalizeText).filter((value) => {
    if (!value || seen.has(value.toLowerCase())) return false;
    seen.add(value.toLowerCase());
    return true;
  });
}

function buildLocation(job, remote) {
  const directLocation = normalizeText(job.job_location);
  if (directLocation) return directLocation;
  const location = uniqueStrings([job.job_city, job.job_state, job.job_country]).join(', ');
  return location || (remote ? 'Remote' : null);
}

function normalizeEmploymentType(value) {
  const type = normalizeText(value)?.toUpperCase().replace(/[\s_-]/g, '');
  const types = { FULLTIME: 'Full-time', PARTTIME: 'Part-time', CONTRACTOR: 'Contract', CONTRACT: 'Contract', PERMANENT: 'Full-time', TEMPORARY: 'Temporary', INTERN: 'Internship', INTERNSHIP: 'Internship' };
  return types[type] || 'Unknown';
}

function firstNumber(...values) {
  for (const value of values) {
    if (value === null || value === undefined || value === '') continue;
    const number = typeof value === 'number' ? value : Number(value);
    if (Number.isFinite(number)) return number;
  }
  return null;
}

function normalizePostedAt(job) {
  const value = job.job_posted_at_datetime_utc ?? job.job_posted_at_timestamp ?? job.job_posted_at;
  if (value === null || value === undefined || value === '') return null;
  const numericValue = Number(value);
  const date = typeof value === 'number' || /^\d+$/.test(String(value)) ? new Date(numericValue > 1e12 ? numericValue : numericValue * 1000) : new Date(value);
  return Number.isNaN(date.getTime()) ? null : date.toISOString();
}

function assertMandatoryFields(fields) {
  const missing = Object.entries(fields).filter(([, value]) => !value).map(([name]) => name);
  if (missing.length) throw new Error(`JSearch job is missing mandatory field(s): ${missing.join(', ')}.`);
}

function normalizeJSearchJob(job) {
  const title = normalizeText(job.job_title);
  const company = normalizeText(job.employer_name);
  const description = normalizeMultilineText(job.job_description);
  const applyUrl = normalizeText(job.job_apply_link);
  const remote = job.job_is_remote === true;
  const location = buildLocation(job, remote);
  assertMandatoryFields({ title, company, location, description, apply_url: applyUrl });

  const skills = uniqueStrings(job.job_required_skills);
  const qualifications = uniqueStrings(job.job_highlights?.Qualifications);
  const benefits = uniqueStrings([...toArray(job.job_benefits), ...toArray(job.job_highlights?.Benefits)]);

  return {
    job_id: `${title}|${company}`.toLowerCase(),
    title, company, location, country: normalizeText(job.job_country),
    remote,
    hybrid: /\bhybrid\b/i.test([job.job_title, job.job_location, job.job_description].filter((value) => typeof value === 'string').join(' ')),
    employment_type: normalizeEmploymentType(job.job_employment_type),
    seniority: null,
    salary: firstNumber(job.job_min_salary, job.job_max_salary),
    currency: normalizeText(job.job_salary_currency),
    description,
    requirements: normalizeMultilineText(qualifications.join('\n')) || normalizeText(skills.join(', ')),
    benefits: normalizeMultilineText(benefits.join('\n')),
    technologies: skills, industry: null, keywords: skills, company_size: null,
    posted_at: normalizePostedAt(job), apply_url: applyUrl, source: 'JSearch',
    language: normalizeText(job.job_language) || 'en', raw_source: job,
  };
}

return $input.all().flatMap((item) => item.json.data.map((job) => ({
  json: normalizeJSearchJob(job),
})));
